const fs = require('fs');

const MOD = 998244353;

function solve() {
    const data = fs.readFileSync(0, 'utf-8').trim();
    if (!data) return;
    const n = parseInt(data, 10);

    if (n % 2 === 1) {
        console.log(0);
        return;
    }

    const m = n / 2;
    const maxN = m;

    const fact = new Array(maxN + 1);
    const invFact = new Array(maxN + 1);
    fact[0] = 1;
    for (let i = 1; i <= maxN; i++) {
        fact[i] = (fact[i - 1] * i) % MOD;
    }
    invFact[maxN] = modPow(fact[maxN], MOD - 2);
    for (let i = maxN; i > 0; i--) {
        invFact[i - 1] = (invFact[i] * i) % MOD;
    }

    function C(n, k) {
        if (k < 0 || k > n) return 0;
        return (fact[n] * invFact[k] % MOD) * invFact[n - k] % MOD;
    }

    let ans = 0;
    const maxK = Math.floor(m / 2);
    for (let k = 0; k <= maxK; k++) {
        const waysChoose = C(m, 2 * k);
        const waysPair = fact[2 * k] * modPow(2, k) % MOD * invFact[k] % MOD;
        // Actually waysPair = (2k)! / (2^k k!)
        // Let's compute carefully:
        // waysPair = fact[2*k] * invFact[k] % MOD * modPow(inv2, k) % MOD
        // but modPow(2, k) in denominator is modPow(inv2, k).
        // The formula derived: m! / ( (m-2k)! * k! * 2^k )
        // term = fact[m] * invFact[m - 2*k] % MOD * invFact[k] % MOD * modPow(inv2, k) % MOD

        const term = fact[m] * invFact[m - 2 * k] % MOD * invFact[k] % MOD * modPow((MOD + 1) / 2, k) % MOD;

        const pow4 = modPow(4, m - 2 * k);
        ans = (ans + term * pow4) % MOD;
    }

    console.log(ans);
}

function modPow(a, e) {
    let res = 1;
    let cur = a % MOD;
    while (e > 0) {
        if (e & 1) res = res * cur % MOD;
        cur = cur * cur % MOD;
        e >>= 1;
    }
    return res;
}

solve();
